            aOrbiterK = ((aWandererJ + RotL64(aCross, 35U)) + RotL64(aCarry, 35U)) + 0xD85EC5072F828AE3ULL;
            aOrbiterD = (((aWandererE + RotL64(aPrevious, 29U)) + RotL64(aCarry, 57U)) + 0x1FBB3B09F063422DULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterI = (aWandererI + RotL64(aScatter, 41U)) + 0x56A72C29203BA960ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xB1089D3A382E2DD0ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0x935A83CB59716770ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x370A26762BB64417ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x5F745C4D9124652CULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0xB813E080AFAAF539ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 28U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x7C4F6C99F557ECA1ULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xB5E61D9F3C83D430ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0x9E1CDA30624B9BE7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x54A0DB29A22C4AF1ULL), 51U);
