            aWandererK = aWandererK ^ (((RotL64(aIngress, 3U) + aOrbiterE) + RotL64(aOrbiterC, 11U)) + aKeyRotateAWandererUpdateSaltE[((aIndex + 5U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aPrevious, 27U) + RotL64(aOrbiterA, 29U)) + aOrbiterD);
            aWandererA = aWandererA ^ (((RotL64(aCross, 47U) + aOrbiterD) + RotL64(aOrbiterE, 3U)) + aKeyRotateAWandererUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aIngress, 43U) + aOrbiterF) + RotL64(aOrbiterK, 41U)) + RotL64(aCarry, 39U));
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 35U) + aOrbiterK) + RotL64(aOrbiterA, 5U));
            aWandererC = aWandererC + (((RotL64(aCross, 60U) + RotL64(aOrbiterA, 58U)) + aOrbiterC) + RotL64(aCarry, 3U));
            //
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererA, 42U));
