            //
            aScatter = (RotL64(aPrevious, 41U) + RotL64(aCross, 53U)) + (RotL64(aCarry, 3U) ^ RotL64(aIngress, 28U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = ((aWandererK + RotL64(aIngress, 43U)) + RotL64(aCarry, 57U)) + 0x41C75C2B2FC3E6BBULL;
            aOrbiterA = (aWandererA + RotL64(aCross, 22U)) + 0xC59AC8C8B5C0F133ULL;
            aOrbiterB = ((aWandererH + RotL64(aPrevious, 51U)) + RotL64(aCarry, 37U)) + 0x478883645A13D9E0ULL;
            aOrbiterK = (((aWandererJ + RotL64(aScatter, 35U)) + RotL64(aCarry, 19U)) + 0x44DB54CC57D34B37ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterJ = (aWandererC + RotL64(aIngress, 29U)) + 0xDDD76F3F8558C770ULL;
            aOrbiterC = (aWandererE + RotL64(aScatter, 11U)) + 0x28D7591DE54ADE12ULL;
            aOrbiterI = ((aWandererD + RotL64(aCross, 57U)) + 0xE0E8AA42505E9F51ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 3U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x14B3D22A3E3BE283ULL;
