            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x509DB6B61D840D1BULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 24U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xBCE90FEDED9C0779ULL), 53U);
