            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x9FAE37EB5C79E426ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x3C3DF16070474617ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x0A54CCBA0556EF6BULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xA2CEF99D77AFB090ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0x90317DA8C4299C54ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 11U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x3A539E4695ED6215ULL), 3U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterE, 27U);
            aIngress = aIngress + (RotL64(aOrbiterB, 35U) ^ aOrbiterK);
            aIngress = aIngress + (RotL64(aOrbiterI, 11U) ^ aOrbiterC);
            aIngress = aIngress + RotL64(aOrbiterJ, 42U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererJ = aWandererJ + (((RotL64(aIngress, 29U) + RotL64(aOrbiterB, 57U)) + aOrbiterI) + RotL64(aCarry, 57U));
