        //
        // Ingress:
        //      aFuseLaneA (-->), aWindLaneC (-->), aKeyRowReadB (-->), aShadowLaneB (<-?->)
        //
        // Cross:
        //      aWindLaneA (<--), aWindLaneD (<--), aPoisonLaneC (<--), aMagmaLaneC (<-?->)
        //
