            aCross ^= (RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 8743U)) & S_BLOCK1], 44U) ^ RotL64(aMagmaLaneC[((S_BLOCK1 - aIndex + 12216U)) & S_BLOCK1], 35U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 27U) ^ RotL64(aCross, 11U)) ^ (RotL64(aCarry, 57U) + RotL64(aIngress, 40U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = (aWandererF + RotL64(aCross, 4U)) + 0xF082EFBDDFAB7CB4ULL;
            aOrbiterD = ((aWandererI + RotL64(aPrevious, 19U)) + RotL64(aCarry, 27U)) + 0xDE1C3E8CB7D9771AULL;
            aOrbiterE = ((aWandererK + RotL64(aIngress, 37U)) + RotL64(aCarry, 3U)) + 0x88E1EC5741F6361BULL;
            aOrbiterI = (((aWandererH + RotL64(aScatter, 47U)) + RotL64(aCarry, 53U)) + 0xD2FAE5483EFBA0E5ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 6U)) & S_SALT1];
            aOrbiterB = (aWandererD + RotL64(aPrevious, 27U)) + 0x988C11A1E2F16257ULL;
            aOrbiterA = (aWandererE + RotL64(aScatter, 11U)) + 0x7B6CA40CDEB60766ULL;
            aOrbiterK = ((aWandererG + RotL64(aCross, 53U)) + 0x48875ACABA31588CULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0xBA81C3F8A71FC67CULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x77CA1106038885F9ULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 10U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x94C5285CED0101CBULL), 27U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x575256971633B85AULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x5053FAFA5C5AB104ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x6EB88ADC07CD6995ULL), 53U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0xC0F4C6CCE102C173ULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x66128D20BE4E1EA3ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x5F817C539E1971C9ULL), 47U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0x2C8C560A3D392C63ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x308D364C1014906BULL;
            aOrbiterI = RotL64((aOrbiterI * 0x028440AD445BB4AFULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0xF7582F3AABB3A5C3ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x47B39C9583B1852DULL;
            aOrbiterA = RotL64((aOrbiterA * 0x206E2E9F4C37860DULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xB8D955A478DC080AULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x3412167128701132ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x85D96AD2D5C5E913ULL), 5U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0xDCD621C1C89AFE50ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x824C6A60328E5D3EULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC744B6A79B97BEABULL), 19U);
            //
            aIngress = RotL64(aOrbiterF, 51U) ^ aOrbiterK;
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterA, 13U));
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterI, 43U));
            aIngress = aIngress + RotL64(aOrbiterD, 5U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererH = aWandererH + ((((RotL64(aScatter, 51U) + aOrbiterK) + RotL64(aOrbiterA, 23U)) + RotL64(aCarry, 39U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 25U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aCross, 3U) + RotL64(aOrbiterB, 43U)) + aOrbiterE) + aKeyRotateAWandererUpdateSaltB[((aIndex + 4U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aPrevious, 29U) + aOrbiterB) + RotL64(aOrbiterA, 37U)) + RotL64(aCarry, 53U));
            aWandererK = aWandererK ^ ((RotL64(aIngress, 43U) + aOrbiterD) + RotL64(aOrbiterI, 57U));
